CREATE TABLE cloud_projects(project_id text PRIMARY KEY, local_project_id text NOT NULL, owner_scope_ref text NOT NULL, created_at timestamptz(6) NOT NULL DEFAULT clock_timestamp());
CREATE TABLE execution_sessions(session_id text PRIMARY KEY, project_id text NOT NULL REFERENCES cloud_projects, execution_epoch_id text NOT NULL, owner_host_context text NOT NULL, source_input_ref jsonb NOT NULL, policy jsonb NOT NULL, immutable_payload jsonb NOT NULL, created_at timestamptz(6) NOT NULL DEFAULT clock_timestamp());
CREATE TABLE project_execution_slots(project_id text PRIMARY KEY REFERENCES cloud_projects, session_id text NOT NULL REFERENCES execution_sessions, execution_epoch_id text NOT NULL, state text NOT NULL CHECK(state IN ('active','needs_resolution')));
CREATE TABLE datasets(dataset_id text PRIMARY KEY, project_id text NOT NULL REFERENCES cloud_projects, source_mode text NOT NULL CHECK(source_mode IN ('software_in_loop','physical_device','generated_load')), purpose text NOT NULL CHECK(purpose IN ('execution','telemetry_only','generated_load')), session_id text REFERENCES execution_sessions, next_ingress_sequence bigint NOT NULL DEFAULT 0 CHECK(next_ingress_sequence BETWEEN 0 AND 9007199254740991), visible_frontier bigint NOT NULL DEFAULT 0 CHECK(visible_frontier=next_ingress_sequence), CHECK((purpose='execution')=(session_id IS NOT NULL)), CHECK((purpose='generated_load')=(source_mode='generated_load')));
CREATE UNIQUE INDEX dataset_session ON datasets(session_id) WHERE session_id IS NOT NULL;
CREATE TABLE device_bindings(binding_id text PRIMARY KEY, project_id text NOT NULL REFERENCES cloud_projects, device_id text NOT NULL, principal_scope_ref text NOT NULL, definition_ref jsonb NOT NULL, capability_map jsonb NOT NULL, UNIQUE(project_id,device_id));
CREATE TABLE device_boots(device_binding_id text NOT NULL REFERENCES device_bindings, device_boot_id text NOT NULL, session_id text NOT NULL REFERENCES execution_sessions, execution_epoch_id text NOT NULL, state text NOT NULL CHECK(state IN ('active','retired')), retired_at_published_revision bigint, PRIMARY KEY(device_binding_id,device_boot_id), CHECK((state='retired')=(retired_at_published_revision IS NOT NULL)));
CREATE UNIQUE INDEX active_boot ON device_boots(device_binding_id) WHERE state='active';
CREATE TABLE commands(command_id text PRIMARY KEY, session_id text NOT NULL REFERENCES execution_sessions, execution_epoch_id text NOT NULL, logical_job_id text NOT NULL, phase_id text NOT NULL, attempt_ordinal bigint NOT NULL, device_binding_id text NOT NULL REFERENCES device_bindings, immutable_payload jsonb NOT NULL, target_device_boot_id text NOT NULL, delivery_state text NOT NULL CHECK(delivery_state IN ('queued','claimed','withdrawn')), cancel_requested boolean NOT NULL DEFAULT false, closed_by_host_at timestamptz(6), created_at timestamptz(6) NOT NULL DEFAULT clock_timestamp(), FOREIGN KEY(device_binding_id,target_device_boot_id) REFERENCES device_boots, UNIQUE(session_id,logical_job_id,phase_id,attempt_ordinal));
CREATE UNIQUE INDEX live_command ON commands(session_id,logical_job_id,phase_id) WHERE closed_by_host_at IS NULL;
CREATE INDEX commands_poll ON commands(session_id,device_binding_id,delivery_state);
CREATE TABLE device_poll_requests(binding_id text NOT NULL REFERENCES device_bindings, device_boot_id text NOT NULL, poll_request_id text NOT NULL, session_id text NOT NULL REFERENCES execution_sessions, execution_epoch_id text NOT NULL, command_id text REFERENCES commands, outcome text NOT NULL CHECK(outcome IN ('command','empty')), immutable_request jsonb NOT NULL, observation_probe jsonb, response_payload jsonb NOT NULL, PRIMARY KEY(binding_id,device_boot_id,poll_request_id));
CREATE TABLE device_events(receipt_id text PRIMARY KEY, dataset_id text NOT NULL REFERENCES datasets, ingress_id bigint NOT NULL, device_ref text NOT NULL, device_binding_id text REFERENCES device_bindings, device_boot_id text, device_sequence bigint NOT NULL, session_id text, execution_epoch_id text, event_kind text NOT NULL CHECK(event_kind IN ('receipt','telemetry','generated_load')), typed_payload jsonb NOT NULL, cloud_received_at timestamptz(6) NOT NULL, batch_id text, batch_ordinal bigint, command_id text, UNIQUE(dataset_id,ingress_id));
CREATE UNIQUE INDEX live_event_sequence ON device_events(device_binding_id,device_boot_id,device_sequence) WHERE device_binding_id IS NOT NULL;
CREATE UNIQUE INDEX load_batch_ordinal ON device_events(dataset_id,batch_id,batch_ordinal) WHERE event_kind='generated_load';
CREATE UNIQUE INDEX load_device_sequence ON device_events(dataset_id,device_ref,device_sequence) WHERE event_kind='generated_load';
CREATE INDEX event_device_time ON device_events(dataset_id,device_ref,cloud_received_at,ingress_id);
CREATE INDEX event_command ON device_events(dataset_id,command_id,ingress_id);
CREATE TABLE receipt_admissions(receipt_id text NOT NULL REFERENCES device_events, execution_revision bigint NOT NULL, session_id text NOT NULL REFERENCES execution_sessions, execution_epoch_id text NOT NULL, decision text NOT NULL CHECK(decision IN ('applied','duplicate','rejected','pending_dependency')), host_admission_sequence bigint NOT NULL, host_received_elapsed_ms bigint NOT NULL, business_effect_committed boolean NOT NULL, reason text, typed_payload jsonb NOT NULL, PRIMARY KEY(receipt_id,execution_revision));
CREATE INDEX admissions_session ON receipt_admissions(session_id,execution_epoch_id,execution_revision);
CREATE TABLE execution_snapshots(session_id text NOT NULL REFERENCES execution_sessions, execution_epoch_id text NOT NULL, execution_revision bigint NOT NULL, snapshot_payload jsonb NOT NULL, publication_payload jsonb NOT NULL, host_observed_until_ms bigint NOT NULL, created_at timestamptz(6) NOT NULL DEFAULT clock_timestamp(), observation_frontier bigint NOT NULL, PRIMARY KEY(session_id,execution_epoch_id,execution_revision));
CREATE TABLE execution_heads(session_id text PRIMARY KEY REFERENCES execution_sessions, execution_epoch_id text NOT NULL, published_revision bigint NOT NULL, FOREIGN KEY(session_id,execution_epoch_id,published_revision) REFERENCES execution_snapshots);
CREATE TABLE execution_cutoffs(session_id text NOT NULL REFERENCES execution_sessions, cutoff_ms bigint NOT NULL, execution_epoch_id text NOT NULL, snapshot_revision bigint NOT NULL, PRIMARY KEY(session_id,cutoff_ms), FOREIGN KEY(session_id,execution_epoch_id,snapshot_revision) REFERENCES execution_snapshots);
CREATE TABLE execution_inputs(session_id text NOT NULL REFERENCES execution_sessions, execution_epoch_id text NOT NULL, frozen_inputs jsonb NOT NULL, PRIMARY KEY(session_id,execution_epoch_id));
CREATE TABLE execution_observations(session_id text NOT NULL REFERENCES execution_sessions, execution_epoch_id text NOT NULL, record_sequence bigint NOT NULL, execution_revision bigint NOT NULL, at_host_ms bigint NOT NULL, object_kind text NOT NULL CHECK(object_kind IN ('item','job','device','logical_work','attempt')), object_id text NOT NULL, typed_state jsonb NOT NULL, PRIMARY KEY(session_id,execution_epoch_id,record_sequence));
CREATE INDEX observation_history ON execution_observations(session_id,execution_epoch_id,object_kind,object_id,at_host_ms,record_sequence);
